// TestGenerateDaemonWorker tests that daemon worker generates correctly and that
// its loop timers stay overridable through env vars — as worker fields read in
// Create, not as package-level variables reading the environment in their own
// initializers (TOOLS-31). The read now happens at a point main can be seen to
// reach, instead of as a side effect of importing the package.
func TestGenerateDaemonWorker(t *testing.T) {
	curDir, err := os.Getwd()
	if err != nil {
		t.Fatalf("Error getting current directory: %v", err)
	}

	configDir := filepath.Join(curDir, "..", "test", "docker-integration", "configs", "worker-daemon")
	tmpDir := t.TempDir()

	out, err := ExecCommand(filepath.Join(curDir, ".."), "go", []string{
		"run", filepath.Join(curDir, "..", "cmd", "go-project-starter", "main.go"),
		"--target", tmpDir,
		"--configDir", configDir,
		"--config", "project.yaml",
	}, "Generate daemon worker project ("+tmpDir+")")
	if err != nil {
		t.Fatalf("Error creating project: %s\n%s", err, out)
	}

	t.Logf("Daemon worker project created in %s: %s", tmpDir, out)

	assertFileContains := func(t *testing.T, relPath string, expected []string) {
		t.Helper()

		content, err := os.ReadFile(filepath.Join(tmpDir, relPath))
		if err != nil {
			t.Fatalf("Error reading %s: %v", relPath, err)
		}

		s := string(content)
		for _, exp := range expected {
			if !strings.Contains(s, exp) {
				t.Errorf("%s should contain %q", relPath, exp)
			}
		}
	}

	assertFileContains(t, "internal/app/worker/daemon/psg_daemon_gen.go", []string{
		`WorkerName      = "daemon"`,
		"func durationFromEnv(key string, def time.Duration) time.Duration",
		`durationFromEnv("WORKER_DAEMON_ERROR_TIMEOUT"`,
		`durationFromEnv("WORKER_DAEMON_NEW_CYCLE_TIMEOUT"`,
		// Read in the constructor, into fields, with the defaults behind
		// accessors so a worker built as &Worker{} does not spin on a zero timer.
		"loopErrorTimeout:    durationFromEnv(",
		"loopNewCycleTimeout: durationFromEnv(",
		"func (w *Worker) errorTimeout() time.Duration",
		"func (w *Worker) newCycleTimeout() time.Duration",
		"timer = time.NewTimer(w.errorTimeout())",
		"timer = time.NewTimer(w.newCycleTimeout())",
	})

	daemon, err := os.ReadFile(filepath.Join(tmpDir, "internal/app/worker/daemon/psg_daemon_gen.go"))
	if err != nil {
		t.Fatalf("Error reading psg_daemon_gen.go: %v", err)
	}

	for _, gone := range []string{
		"ErrorTimeout    = durationFromEnv(",
		"NewCycleTimeout = durationFromEnv(",
	} {
		if strings.Contains(string(daemon), gone) {
			t.Errorf("psg_daemon_gen.go still reads the environment in a package-level "+
				"var initializer (%q): gochecknoglobals is enabled in the generated config", gone)
		}
	}
}

// TestGenerateTelegramWorkerGoVersion tests that a project with a telegram worker is
// generated on a supported Go version and carries no workaround pin of
// github.com/gofrs/uuid/v5.
//
// The telegram driver templates import gofrs/uuid/v5 directly. Its v5.5.0+ releases
// declare `go 1.25`, which used to break `go mod tidy` in projects generated on Go 1.24
// (TOOLS-4). The fix is the Go version bump, not freezing the dependency on v5.4.0, so
// go.mod must resolve uuid itself instead of carrying a hardcoded require line.
//
// The floor is deliberately a *supported* release (Go supports the two latest minors):
// generating on an EOL version only defers the next dependency-drift break, which is
// why the first attempt at this fix (Go 1.25 + goimports pinned to v0.49.0) was
// rejected on review.
func TestGenerateTelegramWorkerGoVersion(t *testing.T) {
	curDir, err := os.Getwd()
	if err != nil {
		t.Fatalf("Error getting current directory: %v", err)
	}

	configDir := filepath.Join(curDir, "..", "test", "docker-integration", "configs", "worker-telegram")
	tmpDir := t.TempDir()

	out, err := ExecCommand(filepath.Join(curDir, ".."), "go", []string{
		"run", filepath.Join(curDir, "..", "cmd", "go-project-starter", "main.go"),
		"--target", tmpDir,
		"--configDir", configDir,
		"--config", "project.yaml",
	}, "Generate telegram worker project ("+tmpDir+")")
	if err != nil {
		t.Fatalf("Error creating project: %s\n%s", err, out)
	}

	content, err := os.ReadFile(filepath.Join(tmpDir, "go.mod"))
	if err != nil {
		t.Fatalf("Error reading go.mod: %v", err)
	}

	s := string(content)

	major, minor, err := goDirective(s)
	if err != nil {
		t.Fatalf("Error parsing go directive: %v\n%s", err, s)
	}

	if major != 1 || minor < minSupportedGoMinor {
		t.Errorf("go.mod should declare go >= 1.%d (a supported release), got %d.%d",
			minSupportedGoMinor, major, minor)
	}

	if strings.Contains(s, "github.com/gofrs/uuid/v5 v") {
		t.Errorf("go.mod should not pin github.com/gofrs/uuid/v5 — the Go version bump "+
			"removed the need for it, got:\n%s", s)
	}

	// The same rule applies to the toolchain the generated Makefile installs:
	// pinning goimports to an old release to stay installable on an old Go is
	// the workaround this bump replaces.
	makefile, err := os.ReadFile(filepath.Join(tmpDir, "Makefile"))
	if err != nil {
		t.Fatalf("Error reading Makefile: %v", err)
	}

	if !strings.Contains(string(makefile), "goimports@latest") {
		t.Errorf("generated Makefile should install goimports@latest, not a pinned release")
	}
}

// goDirective extracts the major and minor version from the `go` directive of a go.mod.
func goDirective(goMod string) (int, int, error) {
	m := regexp.MustCompile(`(?m)^go\s+(\d+)\.(\d+)`).FindStringSubmatch(goMod)
	if m == nil {
		return 0, 0, fmt.Errorf("no go directive found")
	}

	major, err := strconv.Atoi(m[1])
	if err != nil {
		return 0, 0, fmt.Errorf("parse major %q: %w", m[1], err)
	}

	minor, err := strconv.Atoi(m[2])
	if err != nil {
		return 0, 0, fmt.Errorf("parse minor %q: %w", m[2], err)
	}

	return major, minor, nil
}

// TestObsoleteFileCleanup tests that stale generated files (with disclaimer, no user code)
// are automatically removed during regeneration.
// TestGenerateTelegramWorkerHooks — шаблон telegram-воркера оставляет проекту точки
// расширения: разбор апдейтов (с idle-половиной для GracefulStop), реакция на
// неизвестную команду и ответы на свои ошибки авторизации. Без них проект правит
// Run() руками, и regenerate эти правки стирает.
//
// Точки — поля воркера с сеттерами, которые зовутся из customize, а не
// package-level переменные, которым проект присваивал новое значение (TOOLS-31):
// два воркера в одном процессе больше не делят один набор хуков, а подмена видна
// вызовом, а не записью в переменную чужого пакета.
//
// Заодно: лог JobStarter не пишет апдейт целиком — в сообщении бота может лежать
// токен или пароль.
func TestGenerateTelegramWorkerHooks(t *testing.T) {
	curDir, err := os.Getwd()
	if err != nil {
		t.Fatalf("Error getting current directory: %v", err)
	}

	configDir := filepath.Join(curDir, "..", "test", "docker-integration", "configs", "worker-telegram")
	tmpDir := t.TempDir()

	out, err := ExecCommand(filepath.Join(curDir, ".."), "go", []string{
		"run", filepath.Join(curDir, "..", "cmd", "go-project-starter", "main.go"),
		"--target", tmpDir,
		"--configDir", configDir,
		"--config", "project.yaml",
	}, "Generate telegram worker project ("+tmpDir+")")
	if err != nil {
		t.Fatalf("Error creating project: %s\n%s", err, out)
	}

	read := func(t *testing.T, relPath string) string {
		t.Helper()

		content, err := os.ReadFile(filepath.Join(tmpDir, relPath))
		if err != nil {
			t.Fatalf("Error reading %s: %v", relPath, err)
		}

		return string(content)
	}

	worker := read(t, "internal/app/worker/telegrambot/psg_telegram_gen.go")
	for _, exp := range []string{
		// Поля, сеттеры и дефолты внутри одного воркера.
		"updateHandler         func(ctx context.Context, update tgbotapi.Update)",
		"updateHandlerIdle     func() bool",
		"unknownCommandHandler func(ctx context.Context, w *Worker, rd telegram.RequestData)",
		"func (w *Worker) SetUpdateHandler(h func(ctx context.Context, update tgbotapi.Update), idle func() bool)",
		"func (w *Worker) SetUnknownCommandHandler(h func(ctx context.Context, w *Worker, rd telegram.RequestData))",
		"func (w *Worker) AddErrorHandler(target error, handler func(ctx context.Context) (telegram.Response, error))",
		"func (w *Worker) handleUpdate(ctx context.Context, update tgbotapi.Update)",
		"func (w *Worker) invokeUpdateHandler(ctx context.Context, update tgbotapi.Update)",
		"func (w *Worker) updateHandlerIsIdle() bool",
		// Run и GracefulStop читают точку расширения через воркер.
		"w.invokeUpdateHandler(ctx, update)",
		"== 0 && w.updateHandlerIsIdle()",
	} {
		if !strings.Contains(worker, exp) {
			t.Errorf("psg_telegram_gen.go should contain %q", exp)
		}
	}

	// Прежние package-level хуки: присваивание им из кода проекта должно
	// перестать компилироваться, а не продолжать работать рядом с полями.
	for _, gone := range []string{
		"var updateHandler =",
		"var updateHandlerIdle =",
	} {
		if strings.Contains(worker, gone) {
			t.Errorf("psg_telegram_gen.go still declares the package-level hook %q", gone)
		}
	}

	if strings.Contains(worker, `Interface("Update", update)`) {
		t.Error("JobStarter still logs the whole update: a bot message may carry a token or a password")
	}

	router := read(t, "internal/app/worker/telegrambot/psg_router_gen.go")
	if strings.Contains(router, "var unknownCommandHandler =") {
		t.Error("psg_router_gen.go still declares the package-level unknownCommandHandler hook")
	}

	if got := strings.Count(router, "w.handleUnknownCommand(ctx, requestData)"); got != 3 {
		t.Errorf("the unknown-command hook should be reached on every branch (callback, text, document): got %d calls", got)
	}

	// CustomError был экспортированной мутабельной картой пакета; реестр стал полем.
	workerFile := read(t, "internal/app/worker/telegrambot/psg_worker_gen.go")
	if strings.Contains(workerFile, "var CustomError =") {
		t.Error("psg_worker_gen.go still declares the package-level CustomError registry")
	}

	if !strings.Contains(workerFile, "for _, ce := range w.customErrors {") {
		t.Error("HandleAuthError should walk the worker's own error handlers")
	}
}

// TestGenerateTelegramClientTimeout — HTTP-клиент бота обязан иметь таймаут.
// Библиотека создаёт клиент как &http.Client{} без таймаута вообще, и зависший
// getUpdates висит столько же, сколько живёт бот: в проде это дало два часа молчания
// при живом процессе. Оба прежних конструктора (с эндпоинтом из конфига и без)
// схлопнуты в NewBotAPIWithClient — раздвоение как раз и оставляло дыру на одной ветке.
func TestGenerateTelegramClientTimeout(t *testing.T) {
	curDir, err := os.Getwd()
	if err != nil {
		t.Fatalf("Error getting current directory: %v", err)
	}

	configDir := filepath.Join(curDir, "..", "test", "docker-integration", "configs", "worker-telegram")
	tmpDir := t.TempDir()

	out, err := ExecCommand(filepath.Join(curDir, ".."), "go", []string{
		"run", filepath.Join(curDir, "..", "cmd", "go-project-starter", "main.go"),
		"--target", tmpDir,
		"--configDir", configDir,
		"--config", "project.yaml",
	}, "Generate telegram worker project ("+tmpDir+")")
	if err != nil {
		t.Fatalf("Error creating project: %s\n%s", err, out)
	}

	content, err := os.ReadFile(filepath.Join(tmpDir, "pkg", "drivers", "telegram", "psg_telegram_gen.go"))
	if err != nil {
		t.Fatalf("Error reading telegram driver: %v", err)
	}

	driver := string(content)

	for _, exp := range []string{
		"tgbotapi.NewBotAPIWithClient(botToken, apiEndpoint, redactingClient{inner: &http.Client{Timeout: defaultClientTimeout}})",
		"apiEndpoint = tgbotapi.APIEndpoint",
		`"net/http"`,
		// Логгер библиотеки печатает ошибку запроса как есть, а net/http приводит в ней
		// полный URL — вместе с токеном бота. Обрыв по таймауту, ради которого клиент и
		// заведён, кладёт токен в логи на каждом повторе, если логгер не подменён.
		"tgbotapi.SetLogger(botLogger{out: stdlog.Default()})",
		"func redactToken(msg string) string {",
		// Подмены логгера мало: ошибку Client.Do библиотека отдаёт наружу как есть, и
		// печатают её уже потребители — наш логгер, main и уведомление админу, которое
		// шлёт текст ошибки сообщением в Telegram. Вырезание в клиенте закрывает всех
		// разом.
		"func (c redactingClient) Do(req *http.Request) (*http.Response, error) {",
		"func (e *redactedError) Unwrap() error { return e.err }",
	} {
		if !strings.Contains(driver, exp) {
			t.Errorf("telegram driver should contain %q", exp)
		}
	}

	// Конструкторы без клиента создают &http.Client{} без таймаута — ни одного вызова
	// не должно остаться ни на одной ветке.
	for _, forbidden := range []string{"tgbotapi.NewBotAPI(", "tgbotapi.NewBotAPIWithAPIEndpoint("} {
		if strings.Contains(driver, forbidden) {
			t.Errorf("telegram driver must not use %s — that constructor builds a client without a timeout", forbidden)
		}
	}

	// Таймаут клиента обязан быть больше таймаута длинного опроса, иначе каждый штатный
	// пустой ответ обрывался бы как ошибка и опрос стал бы циклом повторов.
	wait := intFromDriver(t, driver, `defaultWaitTimeout = (\d+)`)
	client := intFromDriver(t, driver, `defaultClientTimeout = (\d+) \* time\.Second`)

	if client <= wait {
		t.Errorf("client timeout (%ds) must be greater than long-poll wait timeout (%ds)", client, wait)
	}

	// Подмена логгера обязана стоять один раз и вне замыкания смены токена: SetLogger
	// пишет в пакетную переменную библиотеки, и повторный вызов из живого опроса —
	// гонка. Выражения вырезания без состояния как раз для того, чтобы хватило одного.
	if n := strings.Count(driver, "tgbotapi.SetLogger("); n != 1 {
		t.Errorf("SetLogger must be called exactly once, got %d", n)
	}
}

func intFromDriver(t *testing.T, driver, pattern string) int {
	t.Helper()

	m := regexp.MustCompile(pattern).FindStringSubmatch(driver)
	if m == nil {
		t.Fatalf("telegram driver should match %s", pattern)
	}

	v, err := strconv.Atoi(m[1])
	if err != nil {
		t.Fatalf("Error parsing %s: %v", m[1], err)
	}

	return v
}

